type CRMDealItem struct {
	ID       UUID   `json:"id"`
	DealID   UUID   `json:"deal_id"`
	Position int64  `json:"position"`
	Name     string `json:"name"`
	// ProductID — Позиция номенклатуры ядра (товар или услуга); нет - строка не из каталога
	ProductID *UUID   `json:"product_id,omitempty"`
	Quantity  float64 `json:"quantity"`
	Unit      string  `json:"unit"`
	// UnitID — Единица из справочника «Единицы измерения» ядра; у строки из каталога - единица карточки товара
	UnitID *UUID `json:"unit_id,omitempty"`
	// Price — Сумма десятичной строкой: «19990.50». Разрядность берёт валюта (MONEY-ROUNDING.md)
	Price           string  `json:"price"`
	DiscountPercent float64 `json:"discount_percent"`
	// VATRate — Ставка НДС записью ядра: «22%», «0%», «без НДС»; пусто - ставка не указана, налог не выделяется
	VATRate string `json:"vat_rate"`
	// Total — Сумма строки со скидкой, как записаны цены сделки (с налогом или без); считает сервер, чтобы клиенты не разошлись на округлении
	Total string `json:"total"`
	// AmountNet — Сумма строки без НДС
	AmountNet string `json:"amount_net"`
	// VATAmount — НДС строки
	VATAmount string `json:"vat_amount"`
	// AmountGross — Сумма строки с НДС
	AmountGross string              `json:"amount_gross"`
	Product     *CRMDealItemProduct `json:"product,omitempty"`
	CreatedAt   string              `json:"created_at"`
	UpdatedAt   string              `json:"updated_at"`
}

type CRMDealItemInput struct {
	Name      string  `json:"name"`
	ProductID *string `json:"product_id,omitempty"`
	Quantity  float64 `json:"quantity"`
	Unit      *string `json:"unit,omitempty"`
	// UnitID — Единица справочника ядра; у строки из каталога сервер берёт единицу карточки товара
	UnitID *string `json:"unit_id,omitempty"`
	// Price — Сумма десятичной строкой: «19990.50». Разрядность берёт валюта (MONEY-ROUNDING.md)
	Price           *string  `json:"price,omitempty"`
	DiscountPercent *float64 `json:"discount_percent,omitempty"`
	// VATRate — Ставка НДС записью ядра: «22%», «20» (станет «20%»), «0%», «без НДС»; пусто - не указана
	VATRate *string `json:"vat_rate,omitempty"`
}

// CRMDealItemProduct — Сведения карточки номенклатуры на момент чтения: CRM их не копирует
type CRMDealItemProduct struct {
	SKU string `json:"sku"`
	// Kind — Вид позиции ядра: goods, service, material, semi_product
	Kind string `json:"kind"`
	// IsStockable — Товар ведётся на складе: только у него есть остаток
	IsStockable bool `json:"is_stockable"`
	// Archived — Карточка в архиве: строка остаётся, новую так не выбрать
	Archived bool `json:"archived"`
}

type CRMDealItemsInput struct {
	Items []CRMDealItemInput `json:"items"`
	// PricesIncludeVAT — Цены строк включают НДС; не передан - не менять
	PricesIncludeVAT *bool `json:"prices_include_vat,omitempty"`
	// AmountFromItems — Сумма сделки = итог состава (по умолчанию). false - сумма, набранная руками, остаётся, а amount_manual показывает, расходится ли она с итогом
	AmountFromItems *bool `json:"amount_from_items,omitempty"`
}

// CRMDealOrder — Заказ покупателя в «Продажах», заведённый из сделки
type CRMDealOrder struct {
	ID UUID `json:"id"`
	// Number — Номер заказа
	Number string `json:"number"`
	// State — Состояние заказа ядра: draft, confirmed, executing, executed, closed, cancelled
	State string `json:"state"`
	// Created — true — заказ заведён этим запросом, false — он уже был
	Created bool `json:"created"`
}

// CRMDealOrderInput — Выбор при создании заказа из сделки
type CRMDealOrderInput struct {
	// CompanyID — Юрлицо, от имени которого продаём. Пусто — единственное действующее юрлицо бизнеса воронки
	CompanyID *UUID `json:"company_id,omitempty"`
}

type CRMDealPatch struct {
	Title *string `json:"title,omitempty"`
	// Amount — Сумма десятичной строкой: «19990.50». Разрядность берёт валюта (MONEY-ROUNDING.md)
	Amount      *string `json:"amount,omitempty"`
	Currency    *string `json:"currency,omitempty"`
	Source      *string `json:"source,omitempty"`
	Description *string `json:"description,omitempty"`
	// FirstMessage — Слова клиента из обращения; правятся, если их записали с ошибкой
	FirstMessage *string `json:"first_message,omitempty"`
	// ClearExpectedClose — Стереть плановую дату закрытия. Пустой expected_close_at значит «не менять», поэтому стирание — этим признаком
	ClearExpectedClose *bool `json:"clear_expected_close,omitempty"`
	// UtmSource — Рекламная метка: источник перехода; пустая строка стирает метку
	UtmSource *string `json:"utm_source,omitempty"`
	// UtmMedium — Рекламная метка: тип трафика; пустая строка стирает метку
	UtmMedium *string `json:"utm_medium,omitempty"`
	// UtmCampaign — Рекламная метка: кампания; пустая строка стирает метку
	UtmCampaign *string `json:"utm_campaign,omitempty"`
	// UtmTerm — Рекламная метка: ключевое слово или аудитория; пустая строка стирает метку
	UtmTerm *string `json:"utm_term,omitempty"`
	// UtmContent — Рекламная метка: объявление или вариант креатива; пустая строка стирает метку
	UtmContent *string `json:"utm_content,omitempty"`
	// LandingPage — Страница, на которую человек пришёл первой; пустая строка стирает
	LandingPage *string `json:"landing_page,omitempty"`
	// Referrer — Страница, с которой человек перешёл на сайт; пустая строка стирает
	Referrer        *string `json:"referrer,omitempty"`
	Probability     *int64  `json:"probability,omitempty"`
	ExpectedCloseAt *string `json:"expected_close_at,omitempty"`
	OwnerID         *int64  `json:"owner_id,omitempty"`
	// CustomerID — Прежний вход: контрагент справочника ERP. Сервер находит или заводит по нему клиента CRM и записывает crm_customer_id; в ответе поля нет.
	CustomerID    *string `json:"customer_id,omitempty"`
	CRMCustomerID *string `json:"crm_customer_id,omitempty"`
	// ClearCustomer — Отвязать клиента от сделки. Пустой crm_customer_id значит «не менять», поэтому отвязка — этим признаком
	ClearCustomer *bool   `json:"clear_customer,omitempty"`
	NextAction    *string `json:"next_action,omitempty"`
	NextActionAt  *string `json:"next_action_at,omitempty"`
	// Custom — Дополнительные поля кабинета: состав задаёт «Настройки → Поля»
	Custom   map[string]json.RawMessage `json:"custom,omitempty"`
	Archived *bool                      `json:"archived,omitempty"`
}

type CRMDealStageHistory struct {
	ID          UUID  `json:"id"`
	DealID      UUID  `json:"deal_id"`
	FromStageID *UUID `json:"from_stage_id,omitempty"`
	ToStageID   UUID  `json:"to_stage_id"`
	ChangedBy   int64 `json:"changed_by"`
	// Kind — Вид записи: created - сделка заведена, move - перенос по этапам, pipeline_change - перенос в другую воронку, reopen - повторное открытие закрытой сделки
	Kind string `json:"kind"`
	// Reason — Причина; заполнена у повторного открытия
	Reason    *string `json:"reason,omitempty"`
	CreatedAt string  `json:"created_at"`
}

type CRMEngagement struct {
	ID         UUID              `json:"id"`
	EntityType string            `json:"entity_type"`
	EntityID   UUID              `json:"entity_id"`
	Kind       CRMEngagementKind `json:"kind"`
	Title      string            `json:"title"`
	// Description — Подробности дела: что обсудить, адрес встречи
	Description string  `json:"description"`
	DueAt       *string `json:"due_at,omitempty"`
	// DoneAt — Пусто, пока дело не выполнено
	DoneAt *string `json:"done_at,omitempty"`
	// RemindAt — Когда напомнить ответственному
	RemindAt *string `json:"remind_at,omitempty"`
	// RemindedAt — Когда напоминание ушло в центр уведомлений
	RemindedAt *string             `json:"reminded_at,omitempty"`
	Repeat     CRMEngagementRepeat `json:"repeat"`
	// EndsAt — Конец дела; срок due_at - его начало
	EndsAt *string `json:"ends_at,omitempty"`
	// AllDay — Дело на весь день: начало и конец - границы суток в поясе timezone
	AllDay *bool `json:"all_day,omitempty"`
	// Timezone — Часовой пояс того, кто планировал (IANA, например Europe/Moscow): в нём встреча стоит в календаре
	Timezone *string `json:"timezone,omitempty"`
	// Location — Адрес встречи; только у видов с галочкой «Адрес»
	Location *string `json:"location,omitempty"`
	// ConferenceURL — Ссылка видеовстречи; только у видов с галочкой «Видеовстреча»
	ConferenceURL *string `json:"conference_url,omitempty"`
	// ConferenceProvider — Откуда ссылка: комната Телемоста, личная ссылка или вставленная руками
	ConferenceProvider *string `json:"conference_provider,omitempty"`
	// ConferenceID — Номер комнаты Телемоста
	ConferenceID *string `json:"conference_id,omitempty"`
	// ParticipantIds — Коллеги-участники (номера сотрудников из GET /api/v1/crm/members); ответственный - организатор и в список не входит
	ParticipantIds []int64 `json:"participant_ids,omitempty"`
	// CalendarEventID — Событие календаря, заведённое из дела
	CalendarEventID *UUID `json:"calendar_event_id,omitempty"`
	// TaskID — Задача модуля «Задачи», заведённая из дела
	TaskID    *UUID   `json:"task_id,omitempty"`
	OwnerID   *int64  `json:"owner_id,omitempty"`
	OwnerName *string `json:"owner_name,omitempty"`
	// EntityTitle — Название карточки дела (в списке «Мои дела»)
	EntityTitle *string `json:"entity_title,omitempty"`
	// Warnings — Дело сохранено, но событие календаря не заведено или не обновлено
	Warnings  []string `json:"warnings,omitempty"`
	CreatedBy int64    `json:"created_by"`
	CreatedAt string   `json:"created_at"`
	UpdatedAt string   `json:"updated_at"`
}

type CRMEngagementInput struct {
	Kind  *CRMEngagementKind `json:"kind,omitempty"`
	Title string             `json:"title"`
	// Description — Подробности дела
	Description *string `json:"description,omitempty"`
	DueAt       *string `json:"due_at,omitempty"`
	// RemindAt — Когда напомнить ответственному; не позже срока
	RemindAt *string              `json:"remind_at,omitempty"`
	Repeat   *CRMEngagementRepeat `json:"repeat,omitempty"`
	// OwnerID — По умолчанию - вызывающий сотрудник
	OwnerID *int64 `json:"owner_id,omitempty"`
	// InCalendar — Поставить дело событием в календарь ответственного; нужен срок
	InCalendar *bool `json:"in_calendar,omitempty"`
	// EndsAt — Конец дела; не раньше срока
	EndsAt *string `json:"ends_at,omitempty"`
	// AllDay — Дело на весь день: начало и конец - границы суток в поясе timezone
	AllDay *bool `json:"all_day,omitempty"`
	// Timezone — Часовой пояс того, кто планировал (IANA, например Europe/Moscow): в нём встреча стоит в календаре
	Timezone *string `json:"timezone,omitempty"`
	// Location — Адрес встречи; только у видов с галочкой «Адрес»
	Location *string `json:"location,omitempty"`
	// ConferenceURL — Ссылка видеовстречи (http/https); только у видов с галочкой «Видеовстреча». Пусто снимает видеовстречу
	ConferenceURL *string `json:"conference_url,omitempty"`
	// ConferenceProvider — Откуда ссылка; пусто при ссылке - вставленная руками
	ConferenceProvider *string `json:"conference_provider,omitempty"`
	// ConferenceID — Номер комнаты Телемоста
	ConferenceID *string `json:"conference_id,omitempty"`
	// ParticipantIds — Коллеги-участники; только у видов с галочкой «Участники». Ответственный - организатор встречи
	ParticipantIds []int64 `json:"participant_ids,omitempty"`
}

type CRMEngagementKind = string

type CRMEngagementKindItem struct {
	// Code — Код вида: то, что ложится в kind дела; после заведения не меняется
	Code string `json:"code"`
	// Label — Подпись вида - право кабинета
	Label     string `json:"label"`
	SortOrder int64  `json:"sort_order"`
	// IsActive — Выключенный вид не предлагается для новых дел, но подписывает старые
	IsActive bool `json:"is_active"`
	// Participants — К делу этого вида можно позвать коллег-участников
	Participants *bool `json:"participants,omitempty"`
	// Location — У дела этого вида есть адрес
	Location *bool `json:"location,omitempty"`
	// Video — У дела этого вида есть видеовстреча: Телемост или своя ссылка
	Video *bool `json:"video,omitempty"`
}

type CRMEngagementPatch struct {
	Kind  *CRMEngagementKind `json:"kind,omitempty"`
	Title *string            `json:"title,omitempty"`
	// Description — Подробности дела
	Description *string `json:"description,omitempty"`
	// DueAt — null снимает срок
	DueAt *string `json:"due_at,omitempty"`
	// RemindAt — null снимает напоминание; новое время снова ставит его в очередь
	RemindAt *string              `json:"remind_at,omitempty"`
	Repeat   *CRMEngagementRepeat `json:"repeat,omitempty"`
	OwnerID  *int64               `json:"owner_id,omitempty"`
	// Done — true закрывает дело, false возвращает в работу; закрытие повторяющегося дела заводит следующее
	Done *bool `json:"done,omitempty"`
	// InCalendar — true ставит в календарь дело, у которого события ещё нет
	InCalendar *bool `json:"in_calendar,omitempty"`
	// EndsAt — Конец дела; null снимает. При переносе срока без конца встреча сохраняет длительность
	EndsAt *string `json:"ends_at,omitempty"`
	// AllDay — Дело на весь день: начало и конец - границы суток в поясе timezone
	AllDay *bool `json:"all_day,omitempty"`
	// Timezone — Часовой пояс того, кто планировал (IANA, например Europe/Moscow): в нём встреча стоит в календаре
	Timezone *string `json:"timezone,omitempty"`
	// Location — Адрес встречи; только у видов с галочкой «Адрес»
	Location *string `json:"location,omitempty"`
	// ConferenceURL — Ссылка видеовстречи (http/https); только у видов с галочкой «Видеовстреча». Пусто снимает видеовстречу
	ConferenceURL *string `json:"conference_url,omitempty"`
	// ConferenceProvider — Откуда ссылка; пусто при ссылке - вставленная руками
	ConferenceProvider *string `json:"conference_provider,omitempty"`
	// ConferenceID — Номер комнаты Телемоста
	ConferenceID *string `json:"conference_id,omitempty"`
	// ParticipantIds — Новый список коллег-участников целиком. Смена вида снимает поля, которых у нового вида нет
	ParticipantIds []int64 `json:"participant_ids,omitempty"`
}

type CRMEngagementRepeat = string

type CRMEngagementTaskInput struct {
	SectionID UUID `json:"section_id"`
	// Title — Название задачи; по умолчанию - название дела
	Title *string `json:"title,omitempty"`
	// Description — Описание задачи; по умолчанию - подробности дела
	Description *string `json:"description,omitempty"`
	// DueAt — Срок задачи; по умолчанию - срок дела
	DueAt *string `json:"due_at,omitempty"`
	// ExecutorID — Исполнитель; по умолчанию - ответственный за дело
	ExecutorID *int64 `json:"executor_id,omitempty"`
}

// CRMExternalLink — Указатель CRM на запись другого модуля; владельцем записи остаётся тот модуль
type CRMExternalLink struct {
	ID         UUID   `json:"id"`
	EntityType string `json:"entity_type"`
	EntityID   UUID   `json:"entity_id"`
	LinkType   string `json:"link_type"`
	ExternalID UUID   `json:"external_id"`
	CreatedAt  string `json:"created_at"`
}

// CRMFunnelStage — Этап воронки для сделок, заведённых в периоде
type CRMFunnelStage struct {
	StageID  UUID    `json:"stage_id"`
	Name     string  `json:"name"`
	LabelKey *string `json:"label_key,omitempty"`
	Category string  `json:"category"`
	// Reached — Дошли до этапа или дальше (пропуск этапа - не потеря)
	Reached int64 `json:"reached"`
	// Current — Сейчас стоят на этапе
	Current int64 `json:"current"`
	// Lost — Проиграны с этого этапа
	Lost int64 `json:"lost"`
	// ToNext — Доля дошедших до следующего этапа (0..1)
	ToNext *float64 `json:"to_next,omitempty"`
	// AvgHours — Сколько часов в среднем сделка стоит на этапе (по уходам с этапа в периоде)
	AvgHours *float64 `json:"avg_hours,omitempty"`
}

type CRMImportApplyInput struct {
	Token string `json:"token"`
}

type CRMImportCandidate struct {
	ID        UUID     `json:"id"`
	Kind      string   `json:"kind"`
	Name      string   `json:"name"`
	Phone     string   `json:"phone"`
	Email     string   `json:"email"`
	INN       string   `json:"inn"`
	MatchedBy []string `json:"matched_by"`
}

type CRMImportConnectInput struct {
	// Account — amoCRM: поддомен или адрес аккаунта (name, name.amocrm.ru, name.kommo.com). Битрикс24: не нужен, портал берётся из адреса вебхука
	Account *string `json:"account,omitempty"`
	// Token — amoCRM: долгосрочный токен администратора. Битрикс24: адрес входящего вебхука https://портал.bitrix24.ru/rest/<номер>/<ключ>/
	Token string `json:"token"`
	// IncludeUnsorted — amoCRM: перенести неразобранное лидами
	IncludeUnsorted *bool `json:"include_unsorted,omitempty"`
	// UpdatedSince — Дозагрузка: только записи, изменённые после этого момента
	UpdatedSince *string `json:"updated_since,omitempty"`
}

type CRMImportCustomField struct {
	Key   string `json:"key"`
	Label string `json:"label"`
	Type  string `json:"type"`
}

type CRMImportDecision struct {
	Action     *string              `json:"action,omitempty"`
	EntityID   *UUID                `json:"entity_id,omitempty"`
	Origin     *string              `json:"origin,omitempty"`
	Candidates []CRMImportCandidate `json:"candidates,omitempty"`
}

type CRMImportDecisionInput struct {
	Action   *string `json:"action,omitempty"`
	EntityID *UUID   `json:"entity_id,omitempty"`
}

type CRMImportDelimiter = string

type CRMImportExtractInput struct {
	Sheets []CRMImportSheetMapping `json:"sheets"`
}

type CRMImportExtractResult struct {
	Run     CRMImportRun        `json:"run"`
	Added   int64               `json:"added"`
	Records int64               `json:"records"`
	Issues  []CRMImportRowIssue `json:"issues"`
}

type CRMImportField struct {
	Key      string `json:"key"`
	Required bool   `json:"required"`
}

type CRMImportFieldTarget struct {
	// Action — field — в заведённое доп. поле, create — в новое поле, которое заведёт импорт, note — текстом «Поля из …», skip — не переносить
	Action string  `json:"action"`
	Key    *string `json:"key,omitempty"`
	Label  *string `json:"label,omitempty"`
	// Type — Тип нового поля: text, number, date или bool
	Type *string `json:"type,omitempty"`
}

type CRMImportFields struct {
	// Entities — Вид листа -> поля: companies, contacts, leads, deals, tasks, notes
	Entities map[string][]CRMImportField `json:"entities"`
}

type CRMImportFileInfo struct {
	Filename string               `json:"filename"`
	Format   string               `json:"format"`
	Sheets   []CRMImportSheetInfo `json:"sheets"`
	// Warnings — Сколько ячеек с формулами прочитано по сохранённому значению
	Warnings int64 `json:"warnings"`
}

type CRMImportInspectInput struct {
	Sheet     string  `json:"sheet"`
	HeaderRow *int64  `json:"header_row,omitempty"`
	Entity    *string `json:"entity,omitempty"`
}

type CRMImportMapping struct {
	Owners    map[string]int64 `json:"owners,omitempty"`
	Pipelines map[string]UUID  `json:"pipelines,omitempty"`
	Stages    map[string]UUID  `json:"stages,omitempty"`
	// LeadStages — Стадии лидов источника (ключ — название стадии) → стадии лидов кабинета (ERP-1619); без сопоставления лид встаёт на первую рабочую стадию
	LeadStages        map[string]UUID   `json:"lead_stages,omitempty"`
	LossReasons       map[string]UUID   `json:"loss_reasons,omitempty"`
	Sources           map[string]string `json:"sources,omitempty"`
	DefaultPipeline   *UUID             `json:"default_pipeline,omitempty"`
	DefaultStage      *UUID             `json:"default_stage,omitempty"`
	DefaultLossReason *UUID             `json:"default_loss_reason,omitempty"`
	DefaultCurrency   *string           `json:"default_currency,omitempty"`
	// UpdateExisting — Повторный перенос обновляет уже перенесённые записи: поле из источника ложится в карточку, если в Akeda его после прошлого переноса не правили (ERP-1619)
	UpdateExisting *bool `json:"update_existing,omitempty"`
	// Fields — Куда ложатся свои поля источника: ключ — «вид записи:поле источника», вид — customer, lead или deal
	Fields map[string]CRMImportFieldTarget `json:"fields,omitempty"`
	// TaskSection — Раздел модуля «Задачи» для задач источника: задача становится задачей задачника со ссылкой на сделку или лид; пусто — делом с пометкой «Задача» (ERP-2891). С проектами источника — раздел для задач без проекта (ERP-2932)
	TaskSection *UUID `json:"task_section,omitempty"`
	// TaskGroups — Куда ложатся задачи проекта источника (рабочей группы Битрикс24): ключ — номер проекта; проект без решения — в task_section (ERP-2932)
	TaskGroups map[string]CRMImportTaskGroupTarget `json:"task_groups,omitempty"`
	// StandaloneTasks — Переносить и задачи источника без сделки и лида — в модуль «Задачи», без карточки CRM (ERP-2932)
	StandaloneTasks *bool `json:"standalone_tasks,omitempty"`
}

type CRMImportMappingInput struct {
	Revision int64            `json:"revision"`
	Mapping  CRMImportMapping `json:"mapping"`
}

type CRMImportNameFormat = string

type CRMImportOptions struct {
	// Values — owners, stages, lead_stages, sources, currencies, loss_reasons; source_tasks — число задач источника (ERP-2891), только если они есть
	Values      map[string][]CRMImportValue `json:"values"`
	Members     []CRMUserRef                `json:"members"`
	Pipelines   []CRMPipeline               `json:"pipelines"`
	LeadSources []CRMLeadSource             `json:"lead_sources"`
	LossReasons []CRMLossReason             `json:"loss_reasons"`
	// LeadStages — Стадии лидов кабинета для сопоставления стадий лидов источника (ERP-1619)
	LeadStages []CRMLeadStage `json:"lead_stages,omitempty"`
	// SourcePipelines — Воронки источника-коннектора; у файла пусто
	SourcePipelines []CRMImportSourcePipeline `json:"source_pipelines"`
	Suggested       CRMImportMapping          `json:"suggested"`
	// Fields — Свои поля источника в пакете (ERP-1619)
	Fields []CRMImportSourceField `json:"fields,omitempty"`
	// CustomFields — Доп. поля кабинета по сущностям: crm.customer, crm.lead, crm.deal
	CustomFields map[string][]CRMImportCustomField `json:"custom_fields,omitempty"`
	// CanCreateFields — Кабинет может завести новое доп. поле из импорта
	CanCreateFields *bool `json:"can_create_fields,omitempty"`
}

