type CoreProductPatch struct {
	SKU        *string          `json:"sku,omitempty"`
	Name       *string          `json:"name,omitempty"`
	Unit       *string          `json:"unit,omitempty"`
	UnitID     *UUID            `json:"unit_id,omitempty"`
	ExternalID *string          `json:"external_id,omitempty"`
	Kind       *CoreProductKind `json:"kind,omitempty"`
	IsSellable *bool            `json:"is_sellable,omitempty"`
	// IsStockable — Хранится на складе. У услуги (kind=service) всегда false: сочетание service + true отклоняется 400. Позицию со складскими движениями нельзя перевести в услугу или снять с неё признак — 409 (ERP-1547)
	IsStockable   *bool `json:"is_stockable,omitempty"`
	IsPurchasable *bool `json:"is_purchasable,omitempty"`
	IsProducible  *bool `json:"is_producible,omitempty"`
	CategoryID    *UUID `json:"category_id,omitempty"`
	FolderID      *UUID `json:"folder_id,omitempty"`
	// VATKind — Вид ставки НДС товара: общая, льготная, нулевая, без НДС; пусто — общая. Процент берётся у юрлица на дату документа (учётная политика)
	VATKind *string `json:"vat_kind,omitempty"`
	// WeightKg — Вес одной базовой единицы, кг, десятичной строкой: до 9 цифр до запятой и до 6 после (0.0127 — это 12,7 г); пусто — не задан
	WeightKg *string `json:"weight_kg,omitempty"`
	// VolumeM3 — Объём одной базовой единицы, м³; пусто — не задан
	VolumeM3 *string `json:"volume_m3,omitempty"`
	// LengthMm — Длина, мм; пусто — не задана
	LengthMm *string `json:"length_mm,omitempty"`
	// WidthMm — Ширина, мм; пусто — не задана
	WidthMm *string `json:"width_mm,omitempty"`
	// HeightMm — Высота, мм; пусто — не задана
	HeightMm *string `json:"height_mm,omitempty"`
	// CountryItemID — Страна происхождения — запись справочника countries (код ОКСМ в code)
	CountryItemID *UUID                     `json:"country_item_id,omitempty"`
	MarkingSource *CoreProductMarkingSource `json:"marking_source,omitempty"`
	// MarkingGroupID — Своя группа маркировки. Обязательна при marking_source = own; при category и none не передаётся — группа со значением отклоняется 400
	MarkingGroupID *UUID `json:"marking_group_id,omitempty"`
	// CustomsCode — Код ТН ВЭД, до десяти цифр
	CustomsCode *string `json:"customs_code,omitempty"`
	// DefaultDimensions — Разрезы учёта по умолчанию: ключ разреза (project, department, cfo) → id записи его справочника (ERP-2849). Продажа услуги берёт их в пустые разрезы шапки. При правке карта заменяется целиком.
	DefaultDimensions map[string]UUID `json:"default_dimensions,omitempty"`
	// Comment — Внутренняя заметка о товаре для сотрудников кабинета: видна в карточке, покупателю и площадкам не уходит. До 2000 символов; пустая строка — заметки нет. Отдаётся карточкой товара (чтение и изменение по id), в строках списка ключа нет.
	Comment *string `json:"comment,omitempty"`
	// OptionSchema — Оси характеристик семейства; у остальных записей пусто
	OptionSchema []CoreProductAxis `json:"option_schema,omitempty"`
	// VariantValues — Значения варианта по осям семейства: ось → код; у семейства с осями — значение каждой оси, у семейства без осей и у остальных записей пусто
	VariantValues map[string]string `json:"variant_values,omitempty"`
	// ShelfLifeValue — Срок годности — число единиц shelf_life_unit (передаётся вместе с ним); null — снять срок, без поля — не менять. Неверный срок — 400
	ShelfLifeValue *int64 `json:"shelf_life_value,omitempty"`
	// ShelfLifeUnit — Единица срока годности: days — дни, months — месяцы; только вместе с shelf_life_value
	ShelfLifeUnit *string `json:"shelf_life_unit,omitempty"`
	// WithoutSeries — «Ведётся без серий»: у товара нет серий и сроков; без поля — не менять
	WithoutSeries *bool `json:"without_series,omitempty"`
}

