type CoreResolvedPrice struct {
	Key       *string `json:"key,omitempty"`
	ProductID UUID    `json:"product_id"`
	// Price — Цена в валюте и режиме НДС документа; пусто — цены нет.
	Price         *string `json:"price,omitempty"`
	PriceTypeID   *UUID   `json:"price_type_id,omitempty"`
	PriceTypeName *string `json:"price_type_name,omitempty"`
	// Source — Откуда цена: manual — введена человеком; contract, channel, contact, default — вид цены договора, канала, контрагента или по умолчанию; contract_price, contact_price — индивидуальная цена; supplier — цена поставщика.
	Source *string `json:"source,omitempty"`
	// SourceName — Имя ступени: договор, канал, контрагент.
	SourceName     *string `json:"source_name,omitempty"`
	ValidFrom      *string `json:"valid_from,omitempty"`
	DocumentID     *UUID   `json:"document_id,omitempty"`
	DocumentNumber *string `json:"document_number,omitempty"`
	Currency       *string `json:"currency,omitempty"`
	// Rate — Курс пересчёта в валюту документа, если валюты разные.
	Rate        *string `json:"rate,omitempty"`
	IncludesVAT bool    `json:"includes_vat"`
	VATAdjusted *bool   `json:"vat_adjusted,omitempty"`
	// Discount — Скидка строки в процентах.
	Discount       *string `json:"discount,omitempty"`
	DiscountSource *string `json:"discount_source,omitempty"`
	// MinPrice — Минимальная цена на дату в валюте и режиме НДС документа.
	MinPrice *string `json:"min_price,omitempty"`
	// Rrp — РРЦ на дату в валюте и режиме НДС документа.
	Rrp *string `json:"rrp,omitempty"`
	// Missing — Почему цены нет: no_price, no_rate, no_product.
	Missing  *string        `json:"missing,omitempty"`
	LastSale *CorePriceSale `json:"last_sale,omitempty"`
	// PriceNotNeeded — Канал документа цены не требует (attrs.price_mode = not_needed, площадка назначает цену сама): пустая цена — не ошибка.
	PriceNotNeeded *bool `json:"price_not_needed,omitempty"`
	// Options — Другие доступные цены товара на дату.
	Options []CorePriceOption `json:"options"`
}

