type DocflowPaymentRequest struct {
	ID     UUID                        `json:"id"`
	Number string                      `json:"number"`
	Status DocflowPaymentRequestStatus `json:"status"`
	// Progress — Ход заявки глазами автора: состояние документа, после согласования — состояние оплаты; exported — платёжка выгружена файлом для интернет-банка (то же слово, что у казначея)
	Progress    string                     `json:"progress"`
	CompanyID   UUID                       `json:"company_id"`
	CompanyName string                     `json:"company_name"`
	ContactID   *UUID                      `json:"contact_id,omitempty"`
	ContactName string                     `json:"contact_name"`
	ItemID      *UUID                      `json:"item_id,omitempty"`
	ItemName    string                     `json:"item_name"`
	Payee       DocflowPaymentRequestPayee `json:"payee"`
	Amount      string                     `json:"amount"`
	Currency    string                     `json:"currency"`
	DueDate     string                     `json:"due_date"`
	Purpose     string                     `json:"purpose"`
	// Justification — Обоснование автора для согласующего
	Justification string `json:"justification"`
	// Priority — Приоритет оплаты
	Priority string `json:"priority"`
	// PaymentMethod — Форма оплаты
	PaymentMethod string `json:"payment_method"`
	// DepartmentID — Подразделение заявки; нет — подразделение автора
	DepartmentID   *UUID   `json:"department_id,omitempty"`
	DepartmentName *string `json:"department_name,omitempty"`
	// ProjectID — Проект заявки (справочник ядра «Проекты»)
	ProjectID   *UUID   `json:"project_id,omitempty"`
	ProjectName *string `json:"project_name,omitempty"`
	// VATRate — Ставка НДС: пусто — не указана, none — без НДС
	VATRate *string `json:"vat_rate,omitempty"`
	// VATAmount — Сумма НДС
	VATAmount *string `json:"vat_amount,omitempty"`
	// ReasonCode — Типовая причина отклонения казначеем: подана вне срока, нет документов, нет денег на дату, дубль, другое
	ReasonCode *string `json:"reason_code,omitempty"`
	// CanCopy — Можно ли завести новую заявку по образцу этой
	CanCopy *bool `json:"can_copy,omitempty"`
	// PayeeAccountID — Расчётный счёт контрагента, из которого сделан снимок реквизитов получателя; нет — реквизиты введены руками
	PayeeAccountID *UUID `json:"payee_account_id,omitempty"`
	// CanRework — Можно ли вернуть заявку на доработку: она согласована, платёжка ещё не в банке, а человек — автор или согласующий
	CanRework *bool `json:"can_rework,omitempty"`
	// CanRefreshPayee — Можно ли обновить получателя из контрагента: автор, заявка с контрагентом — черновик, на доработке или согласованная до банка
	CanRefreshPayee *bool `json:"can_refresh_payee,omitempty"`
	// PaymentOrder — Поля платёжного поручения сверх получателя: КБК, ОКТМО, поля 101–110, УИН, очерёдность
	PaymentOrder *FinancePaymentOrderFields `json:"payment_order,omitempty"`
	// ScheduleID — Регулярная заявка, которая завела эту заявку
	ScheduleID *UUID `json:"schedule_id,omitempty"`
	// SchedulePeriod — Период регулярной заявки, за который заведена заявка
	SchedulePeriod *string `json:"schedule_period,omitempty"`
	// ScheduleName — Название регулярной заявки
	ScheduleName *string `json:"schedule_name,omitempty"`
	// CanRecall — Можно ли вернуть заявку в черновик: автор, заявка на согласовании и ещё не согласована
	CanRecall *bool `json:"can_recall,omitempty"`
	// OverBudgetBy — Кто провёл заявку сверх лимита бюджета кнопкой «Сверх лимита»
	OverBudgetBy *int64 `json:"over_budget_by,omitempty"`
	// OverBudgetByName — Имя того, кто провёл заявку сверх лимита бюджета
	OverBudgetByName *string `json:"over_budget_by_name,omitempty"`
	// OverBudgetAt — Когда заявку провели сверх лимита бюджета
	OverBudgetAt *string `json:"over_budget_at,omitempty"`
	// Budget — Остаток лимита бюджета БДДС по месяцу срока, статье и подразделению; только в карточке нерешённой заявки, когда лимит ей применяется
	Budget *DocflowPaymentRequestBudget `json:"budget,omitempty"`
	// CanSubmitOverBudget — Можно ли отправить заявку сверх лимита: право docflow.flow:over_budget, заявка — черновик или на доработке
	CanSubmitOverBudget *bool `json:"can_submit_over_budget,omitempty"`
	// CanRepeat — Можно ли повторить отклонённую или отозванную заявку новым черновиком
	CanRepeat *bool `json:"can_repeat,omitempty"`
	// BasisBalance — Остаток бумаги-основания: заявлено, оплачено, осталось; только в карточке заявки, у ручного основания нет
	BasisBalance *DocflowPaymentBasisBalance `json:"basis_balance,omitempty"`
	// PossibleDuplicates — Живые заявки той же бумаги на ту же сумму — предупреждение о возможном дубле; только в карточке заявки
	PossibleDuplicates []DocflowPaymentRequestBrief `json:"possible_duplicates,omitempty"`
	Basis              DocflowPaymentRequestBasis   `json:"basis"`
	// Destination — Куда ушла согласованная заявка: снимок флага маршрута
	Destination string `json:"destination"`
	// Reason — Причина отказа, возврата на доработку или отклонения казначеем
	Reason  *string                       `json:"reason,omitempty"`
	Payment *DocflowPaymentRequestPayment `json:"payment,omitempty"`
	// FinanceRequestID — Строка очереди оплат модуля finance, куда ушла согласованная заявка
	FinanceRequestID *UUID `json:"finance_request_id,omitempty"`
	// ApprovalAuto — Согласована автоматически: маршрута для заявки нет и согласование не обязательно, прохода согласования не было
	ApprovalAuto bool `json:"approval_auto"`
	// RejectedByFinance — Согласованную заявку отклонил казначей в модуле finance; причина — в reason
	RejectedByFinance bool   `json:"rejected_by_finance"`
	CreatedBy         *int64 `json:"created_by,omitempty"`
	CreatedByName     string `json:"created_by_name"`
	CreatedAt         string `json:"created_at"`
	UpdatedAt         string `json:"updated_at"`
	Version           int64  `json:"version"`
	CanEdit           bool   `json:"can_edit"`
	CanSubmit         bool   `json:"can_submit"`
	CanCancel         bool   `json:"can_cancel"`
}

