type DocflowYandexKitSyncState struct {
	LastRunAt     *string `json:"last_run_at"`
	LastSuccessAt *string `json:"last_success_at"`
	// LastCode — ok, token_rejected, rate_limited, unavailable, not_configured, retail_buyer_missing; пусто — опроса не было
	LastCode      string `json:"last_code"`
	OrdersSeen    int64  `json:"orders_seen"`
	OrdersChanged int64  `json:"orders_changed"`
	// CursorAt — До какого момента изменения KIT прочитаны; null — опроса не было
	CursorAt *string `json:"cursor_at"`
	// WarningCode — Режим подтверждения в подключении (options.confirm_mode) и в KIT разошёлся: kit_auto_confirm — в KIT осталось автоподтверждение, kit_manual_confirm — заказы ждут ручного подтверждения в KIT; пусто — расхождения не видно
	WarningCode string `json:"warning_code"`
	// StockRunAt — Когда последний раз передавались остатки в KIT (options.stock_sync); null — не передавались
	StockRunAt *string `json:"stock_run_at"`
	// StockCode — Итог передачи остатков: ok, no_kit_warehouse — не выбран склад KIT, no_warehouse — не выбран склад кабинета, launch_pending — склад готовится к запуску и не передаётся, not_configured, token_rejected, rate_limited, unavailable; пусто — передача выключена
	StockCode string `json:"stock_code"`
	// StockSent — Сколько вариантов KIT передано за последний проход (только изменившиеся)
	StockSent int64 `json:"stock_sent"`
	// StockUnmatched — Сколько вариантов KIT без нашего товара (или отвергнутых KIT): им остаток не передаётся
	StockUnmatched int64 `json:"stock_unmatched"`
	// StockVariants — Сколько вариантов KIT всего
	StockVariants int64 `json:"stock_variants"`
}

