// MarketplaceStoreCost — Себестоимость магазина на сегодня для списка магазинов: действующая версия учётной настройки, метод оценки склада юрлица и запуск склада площадки. Поля нет — источник себестоимости не задан
type MarketplaceStoreCost struct {
	// Source — manual — ставки в товарах маркетплейса; stock — из складского учёта
	Source string `json:"source"`
	// ValidFrom — С какого дня действует источник
	ValidFrom string `json:"valid_from"`
	// StockMethod — Метод оценки склада юрлица; поля нет — складская политика не настроена
	StockMethod *string `json:"stock_method,omitempty"`
	// StockFrom — Только у stock: с какого дня склад площадки ведётся в учёте
	StockFrom *string `json:"stock_from,omitempty"`
	// StockOpenedOn — Только у stock: день запуска склада площадки; поля нет — склад не запущен, недели ждут запуска
	StockOpenedOn *string `json:"stock_opened_on,omitempty"`
}

// MarketplaceStoreInitialLoad — Первичная загрузка данных магазина сборщиком после ввода ключа.
type MarketplaceStoreInitialLoad struct {
	StoreID  UUID   `json:"store_id"`
	Platform string `json:"platform"`
	// State — ready — обязательные наборы загружены; loading — загрузка идёт; failed — загрузка остановилась; not_connected — ключ не введён или магазин не заведён у сборщика; inactive — магазин выключен; unknown — аналитику прочитать не удалось
	State string `json:"state"`
	// Reason — Стабильный код причины: credentials_missing, store_not_bound, credentials_rejected, ozon_premium_plus_required, platform_rate_limited, interrupted, connection_error, load_failed, analytics_unavailable или код состояния подключения. Текст площадки не публикуется
	Reason *string `json:"reason,omitempty"`
	// Blocking — Решения разбора, привязка карточек, импорт каталога и ввод начального остатка закрыты
	Blocking bool `json:"blocking"`
	// ConnectionStatus — Состояние подключения магазина, как в списке магазинов
	ConnectionStatus string `json:"connection_status"`
	// ConnectionErrorCode — Безопасный код состояния подключения
	ConnectionErrorCode *string `json:"connection_error_code,omitempty"`
	// ReadyAt — Когда готовность подтвердилась; null — ещё нет
	ReadyAt *string `json:"ready_at"`
	// CheckedAt — Момент проверки
	CheckedAt string `json:"checked_at"`
	// Datasets — Наборы данных в порядке показа; пусто, если аналитика недоступна
	Datasets []MarketplaceInitialLoadDataset `json:"datasets"`
}

// MarketplaceStoreInput — Тело создания управляемого подключения. Платформу задаёт маршрут, а external_id назначает MPTrack (у Ламоды и Летуаль — кабинет). Для Ozon нужны ozon_client_id и ozon_api_key, для Wildberries — wb_token, для Яндекс Маркета — ym_api_key (ym_business_id кабинет узнаёт по ключу сам; нужен, только когда ключ видит несколько бизнесов — иначе 422 marketplace.yandex_business_ambiguous), для Ламоды — lamoda_client_id и lamoda_client_secret; Летуаль реквизитов не принимает — ей достаточно названия.
type MarketplaceStoreInput struct {
	Name string `json:"name"`
	// TaxSource — Источник налога магазина: policy — из учётной политики юрлица магазина (tax_percent не нужен и не сохраняется), store — ставка tax_percent вручную. Без поля: store, если передан tax_percent (прежний контракт), иначе policy. Иное значение — 400 marketplace.store_tax_source_invalid
	TaxSource *string `json:"tax_source,omitempty"`
	// TaxPercent — Ручная ставка налога в процентах при источнике store; пустая строка сохраняется как ноль
	TaxPercent *string `json:"tax_percent,omitempty"`
	IsActive   *bool   `json:"is_active,omitempty"`
	HasFbs     *bool   `json:"has_fbs,omitempty"`
	// HasJam — Используется для Wildberries
	HasJam *bool `json:"has_jam,omitempty"`
	// ArticleSizeSeparator — Правило именования артикула Ozon: «БАЗА<разделитель>РАЗМЕР». Список закрыт; пустая строка означает «правила нет». Официальные поля размера площадки всегда старше этого правила
	ArticleSizeSeparator *string `json:"article_size_separator,omitempty"`
	OzonClientID         *string `json:"ozon_client_id,omitempty"`
	OzonAPIKey           *string `json:"ozon_api_key,omitempty"`
	OzonPfClientID       *string `json:"ozon_pf_client_id,omitempty"`
	OzonPfClientSecret   *string `json:"ozon_pf_client_secret,omitempty"`
	// WbToken — Рекомендуется персональный токен класса personal; значение не возвращается
	WbToken *string `json:"wb_token,omitempty"`
	// YmBusinessID — Необязателен: без него кабинет берёт Business ID из магазинов, видных ключу. Строкой; ERP проверяет числовой идентификатор и преобразует его для MPTrack
	YmBusinessID *string `json:"ym_business_id,omitempty"`
	YmAPIKey     *string `json:"ym_api_key,omitempty"`
	// LamodaClientID — client_id Ламоды; он же отпечаток аккаунта — второй магазин с тем же client_id не заводится
	LamodaClientID     *string `json:"lamoda_client_id,omitempty"`
	LamodaClientSecret *string `json:"lamoda_client_secret,omitempty"`
	// Proxy — Необязательный адрес proxy; значение не возвращается
	Proxy *string `json:"proxy,omitempty"`
	// BusinessID — Бизнес магазина. В кабинете с одним бизнесом подставляется сам; при нескольких обязателен — без него ответ 400 marketplace.store_business_required. Бизнес должен входить в область права участника целиком, иначе 403 marketplace.store_business_forbidden; юрлицо учёта магазина потом выбирается только этого бизнеса
	BusinessID *UUID `json:"business_id,omitempty"`
}

type MarketplaceStorePage struct {
	Count   int64              `json:"count"`
	Results []MarketplaceStore `json:"results"`
}

// MarketplaceStorePatch — Меняет пользовательские настройки подключения. external_id изменить нельзя. Отсутствующее или пустое поле реквизита сохраняет прежний секрет.
type MarketplaceStorePatch struct {
	Name *string `json:"name,omitempty"`
	// TaxSource — Смена источника налога с дня tax_effective_from: policy — брать из учётной политики юрлица магазина, store — ручная ставка tax_percent (без неё — прежняя ручная ставка). Без поля: store, если передан tax_percent, иначе налог не меняется. Иное значение — 400 marketplace.store_tax_source_invalid
	TaxSource *string `json:"tax_source,omitempty"`
	// TaxPercent — Ручная ставка при источнике store. Пустая строка оставляет сохранённую ставку
	TaxPercent *string `json:"tax_percent,omitempty"`
	// TaxEffectiveFrom — С какого дня действует новая ставка или новый источник налога (ГГГГ-ММ-ДД). Пусто — с сегодняшнего дня по Москве. Не позже сегодня и не раньше начала действующей версии: прошлые периоды считаются по правилу своего времени
	TaxEffectiveFrom *string `json:"tax_effective_from,omitempty"`
	IsActive         *bool   `json:"is_active,omitempty"`
	HasFbs           *bool   `json:"has_fbs,omitempty"`
	// HasJam — Используется для Wildberries
	HasJam *bool `json:"has_jam,omitempty"`
	// ArticleSizeSeparator — Правило именования артикула Ozon: «БАЗА<разделитель>РАЗМЕР». Список закрыт; пустая строка означает «правила нет». Официальные поля размера площадки всегда старше этого правила. Отсутствие поля оставляет сохранённое правило, пустая строка его снимает
	ArticleSizeSeparator *string `json:"article_size_separator,omitempty"`
	// CatalogAutoCreate — Новые карточки площадки: true — загрузка каталога заводит из них товары сама, false — оставляет новыми до решения человека. Отсутствие поля оставляет сохранённое решение. Применяется к Ozon и Wildberries
	CatalogAutoCreate  *bool   `json:"catalog_auto_create,omitempty"`
	OzonClientID       *string `json:"ozon_client_id,omitempty"`
	OzonAPIKey         *string `json:"ozon_api_key,omitempty"`
	OzonPfClientID     *string `json:"ozon_pf_client_id,omitempty"`
	OzonPfClientSecret *string `json:"ozon_pf_client_secret,omitempty"`
	// WbToken — Пустая строка сохраняет прежний токен
	WbToken *string `json:"wb_token,omitempty"`
	// YmBusinessID — Business ID вводится строкой; ERP проверяет числовой идентификатор и преобразует его для MPTrack. Пустая строка сохраняет прежнее значение
	YmBusinessID   *string `json:"ym_business_id,omitempty"`
	YmAPIKey       *string `json:"ym_api_key,omitempty"`
	LamodaClientID *string `json:"lamoda_client_id,omitempty"`
	// LamodaClientSecret — Пустая строка сохраняет прежний секрет
	LamodaClientSecret *string `json:"lamoda_client_secret,omitempty"`
	// Proxy — Пустая строка сохраняет прежнее значение
	Proxy *string `json:"proxy,omitempty"`
}

// MarketplaceStoreTax — Налог магазина на сегодня с объяснением. Процент от выручки выводится из учётной политики только у режимов с налогом от дохода (УСН и АУСН «доходы», НПД); у ОСНО, УСН/АУСН «доходы минус расходы» и ЕСХН налог берётся с прибыли юрлица и считается в разделе «Налоги», с выручки магазина его нет
type MarketplaceStoreTax struct {
	// Source — Источник: policy — учётная политика юрлица, store — ставка магазина вручную
	Source string `json:"source"`
	// State — manual — ручная ставка магазина; policy — процент из системы налогообложения юрлица; profit_based — режим юрлица берёт налог с прибыли; fixed — патент, фиксированная стоимость; not_set — у юрлица не задана система налогообложения или её ставка; no_company — у магазина не выбрано юрлицо
	State string `json:"state"`
	// Percent — Процент налога с выручки на сегодня, decimal строкой
	Percent string `json:"percent"`
	// CompanyID — Юрлицо магазина, чья учётная политика даёт налог; null — ручная ставка или юрлицо не выбрано
	CompanyID *UUID `json:"company_id"`
	// CompanyName — Название юрлица
	CompanyName *string `json:"company_name,omitempty"`
	// Regime — Система налогообложения юрлица на сегодня
	Regime *string `json:"regime,omitempty"`
	// RegimeRate — Ставка системы налогообложения в процентах, как в учётной политике
	RegimeRate *string `json:"regime_rate,omitempty"`
	// RegimeValidFrom — С какого дня действует система налогообложения юрлица
	RegimeValidFrom *string `json:"regime_valid_from,omitempty"`
}

// MarketplaceStoreWriteKey — Признаки ключа магазина на запись в площадку (марки в сборочные задания FBS); сам ключ не возвращается
