type MarketplaceYandexProduct struct {
	// ID — Составной ключ вида «UUID магазина двоеточие артикул»
	ID        string `json:"id"`
	Store     UUID   `json:"store"`
	StoreName string `json:"store_name"`
	// OfferID — Артикул продавца
	OfferID     string `json:"offer_id"`
	MarketSKU   *int64 `json:"market_sku"`
	ProductName string `json:"product_name"`
	Category    string `json:"category"`
	Vendor      string `json:"vendor"`
	Barcode     string `json:"barcode"`
	// Price — Базовая цена decimal строкой; пустая строка когда цены нет
	Price string `json:"price"`
	// OldPrice — Цена до скидки decimal строкой; пустая строка когда её нет
	OldPrice     string `json:"old_price"`
	Stock        int64  `json:"stock"`
	StatusName   string `json:"status_name"`
	PrimaryImage string `json:"primary_image"`
	// URL — Первая ссылка витрины; пустая строка когда её нет
	URL string `json:"url"`
	// Cost — Себестоимость decimal строкой; null когда она не заведена
	Cost *string `json:"cost"`
	// LinkedProductID — Номенклатура кабинета, к которой привязан артикул канала (core_product_identifier вида channel_article); null — не привязан
	LinkedProductID *UUID `json:"linked_product_id"`
	// LinkedProductSKU — SKU привязанной номенклатуры; пусто без связи
	LinkedProductSKU string `json:"linked_product_sku"`
	// LinkedProductName — Название привязанной номенклатуры; пусто без связи
	LinkedProductName string `json:"linked_product_name"`
	// CostSource — Откуда себестоимость: manual — ставка магазина, stock — склад площадки по партиям (только чтение, ставки у такого магазина нет)
	CostSource string `json:"cost_source"`
	// CostStatus — Только в режиме склада: in_stock — цена партии, которая спишется следующей на складе площадки (при средней — средняя); own_stock — на складе площадки товара нет, цена партии, которая спишется следующей на своих складах юрлица (склад — cost_warehouse_name); out_of_stock — остатка нет нигде, цена последней списанной со склада площадки партии; missing — цены нет, причина в cost_reason
	CostStatus *string `json:"cost_status,omitempty"`
	// CostReason — Почему цены нет: артикул магазина не связан с товаром; склад площадки не заведён или у юрлица на нём нет движений; товара на складе площадки не было; у площадки склада в учёте нет
	CostReason *string `json:"cost_reason,omitempty"`
	// CostProductID — Товар, по партиям которого посчитана цена (связь артикула магазина), — фильтр product_id раздела «Партии»
	CostProductID *string `json:"cost_product_id,omitempty"`
	// CostCompanyID — Юрлицо учётной политики магазина на сегодня — фильтр company_id раздела «Партии»
	CostCompanyID *string `json:"cost_company_id,omitempty"`
	// CostWarehouseID — Склад площадки (MP-WB, MP-OZON), а у own_stock — свой склад партии: фильтр warehouse_id раздела «Партии»
	CostWarehouseID *string `json:"cost_warehouse_id,omitempty"`
	// CostWarehouseName — Название своего склада, с партии которого взята цена (только own_stock)
	CostWarehouseName *string `json:"cost_warehouse_name,omitempty"`
	// CostBatchID — Партия, которая спишется следующей, либо последняя списанная; нет у средней
	CostBatchID *string `json:"cost_batch_id,omitempty"`
	// CostStockQty — Остаток товара юрлица на складе площадки, штуки decimal строкой; 0 — нет на складе
	CostStockQty *string `json:"cost_stock_qty,omitempty"`
}

