type MarkingLabelRequest struct {
	CodeIds []UUID `json:"code_ids,omitempty"`
	// ScanRaw — Сканы этикеток; заносятся в реестр как отдельный скан
	ScanRaw   []string `json:"scan_raw,omitempty"`
	CompanyID UUID     `json:"company_id"`
	// Group — Товарная группа сканов
	Group *string `json:"group,omitempty"`
	// Template — Ключ шаблона; пусто — шаблон из настроек юрлица (58×40)
	Template *string `json:"template,omitempty"`
	// Copies — Копии каждой этикетки
	Copies *int64 `json:"copies,omitempty"`
	// Reason — auto — ненапечатанные коды первой печатью, напечатанные — дубликатом
	Reason string `json:"reason"`
	// Note — Пояснение к дубликату
	Note *string `json:"note,omitempty"`
	// Preset — Формат этикетки; пусто — формат товара, иначе юрлица; outer_duplicate — дубль на внешнюю упаковку (всегда дубликат)
	Preset *string `json:"preset,omitempty"`
	// Fields — Поля этикетки варианта оформления
	Fields []string `json:"fields,omitempty"`
	// Badge — Значок «Честного знака» рядом с маркой; нет поля — как в настройках юрлица
	Badge *bool `json:"badge,omitempty"`
	// Output — Формат ответа: html (по умолчанию) — страница для принтера, pdf — файл, страница = этикетка
	Output *string `json:"output,omitempty"`
	// Channel — Канал штрихкода площадки: код справочника «Каналы продаж» (wildberries, ozon, yandex, lamoda …)
	Channel *string                     `json:"channel,omitempty"`
	Order   *MarkingLabelOrderSelection `json:"order,omitempty"`
	// LabelTemplate — Шаблон этикетки марки; пусто — по умолчанию или размер и вид запроса
	LabelTemplate *string `json:"label_template,omitempty"`
	ContactID     *UUID   `json:"contact_id,omitempty"`
	// ChannelBarcodes — Штрихкод площадки, выбранный у товара (дубли карточек): товар → штрихкод
	ChannelBarcodes map[string]string `json:"channel_barcodes,omitempty"`
	// OnlyUnprinted — Только ни разу не печатанные коды (ERP-2185); все напечатаны — 409 marking.labels.all_printed
	OnlyUnprinted *bool `json:"only_unprinted,omitempty"`
	// RepeatJobs — Повтор окна печати (ERP-3043): коды этих записей журнала печатаются ещё раз дубликатом с причиной note; code_ids, order и scan_raw не нужны
	RepeatJobs []UUID `json:"repeat_jobs,omitempty"`
}

type MarkingLabelTemplate struct {
	Key string `json:"key"`
	// Name — Название на языке запроса
	Name string `json:"name"`
	// Group — Квадратные, прямоугольные рулоны или лист А4
	Group string `json:"group"`
	// Legacy — Прежний размер: печатается по сохранённым настройкам, в выборе не предлагается
	Legacy   bool    `json:"legacy"`
	WidthMm  float64 `json:"width_mm"`
	HeightMm float64 `json:"height_mm"`
	// Sheet — Этикетки раскладываются на лист
	Sheet        bool    `json:"sheet"`
	PerPage      int64   `json:"per_page"`
	PageWidthMm  float64 `json:"page_width_mm"`
	PageHeightMm float64 `json:"page_height_mm"`
}

type MarkingLabelTemplateInput struct {
	Name *string `json:"name,omitempty"`
	Size *string `json:"size,omitempty"`
	// WidthMm — Свой размер (size = custom), шаг 0,5 мм
	WidthMm  *float64            `json:"width_mm,omitempty"`
	HeightMm *float64            `json:"height_mm,omitempty"`
	Format   *string             `json:"format,omitempty"`
	Channel  *string             `json:"channel,omitempty"`
	Blocks   []MarkingLabelBlock `json:"blocks,omitempty"`
	// CopyFrom — Шаблон-образец копии; копия шаблона строками встаёт на холст
	CopyFrom *string `json:"copy_from,omitempty"`
}

type MarkingLabelTemplateList struct {
	Templates              []MarkingLabelTemplateRecord            `json:"templates"`
	Sizes                  []MarkingLabelTemplateListSizesItem     `json:"sizes"`
	Channels               []MarkingLabelTemplateListChannelsItem  `json:"channels"`
	Formats                []string                                `json:"formats"`
	Variables              []MarkingLabelTemplateListVariablesItem `json:"variables"`
	BlockTypes             []string                                `json:"block_types"`
	BarcodeSources         []string                                `json:"barcode_sources,omitempty"`
	CustomSize             *MarkingLabelTemplateListCustomSize     `json:"custom_size,omitempty"`
	DefaultProductTemplate string                                  `json:"default_product_template"`
}

type MarkingLabelTemplateListSizesItem struct {
	Key      string  `json:"key"`
	Name     string  `json:"name"`
	Group    string  `json:"group"`
	WidthMm  float64 `json:"width_mm"`
	HeightMm float64 `json:"height_mm"`
	Sheet    bool    `json:"sheet"`
	// Product — Размер годится этикетке товара
	Product bool `json:"product"`
	Legacy  bool `json:"legacy"`
}

type MarkingLabelTemplateListChannelsItem struct {
	Code  string `json:"code"`
	Label string `json:"label"`
	// EanOnly — Склад канала принимает только EAN/UPC: явный признак записи справочника «Каналы продаж» (attrs.ean_only), по умолчанию выключен; шаблон Code 128 ему не назначается
	EanOnly bool `json:"ean_only"`
	// Used — Канал у кабинета есть на деле: магазин площадки, штрихкоды товаров канала или назначенный шаблон
	Used *bool `json:"used,omitempty"`
}

type MarkingLabelTemplateListVariablesItem struct {
	Key string `json:"key"`
	// Ru — Имя переменной в шаблоне по-русски
	Ru string `json:"ru"`
	// En — Имя переменной в шаблоне по-английски
	En    string   `json:"en"`
	Kinds []string `json:"kinds"`
}

type MarkingLabelTemplateListCustomSize struct {
	MinMm       float64 `json:"min_mm"`
	MaxWidthMm  float64 `json:"max_width_mm"`
	MaxHeightMm float64 `json:"max_height_mm"`
	StepMm      float64 `json:"step_mm"`
}

type MarkingLabelTemplateRecord struct {
	// ID — Идентификатор своего шаблона или ключ системного
	ID     string `json:"id"`
	System bool   `json:"system"`
	Name   string `json:"name"`
	Kind   string `json:"kind"`
	// Size — Ключ размера или custom — свой размер width_mm×height_mm
	Size     string              `json:"size"`
	WidthMm  *float64            `json:"width_mm,omitempty"`
	HeightMm *float64            `json:"height_mm,omitempty"`
	Format   string              `json:"format"`
	Blocks   []MarkingLabelBlock `json:"blocks"`
	// Canvas — Блоки на своих местах (редактор холста); false — шаблон строками прежнего конструктора
	Canvas *bool `json:"canvas,omitempty"`
	// Channel — Канал продаж шаблона: чья карточка даёт штрихкод и артикулы, когда у документа канала нет
	Channel *string `json:"channel,omitempty"`
	// Preset — Вариант оформления системного шаблона
	Preset    *string `json:"preset,omitempty"`
	IsActive  bool    `json:"is_active"`
	UpdatedAt *string `json:"updated_at,omitempty"`
}

type MarkingLabelTemplateRef struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

type MarkingLabelTemplateUpdate struct {
	Name     string              `json:"name"`
	Size     string              `json:"size"`
	WidthMm  *float64            `json:"width_mm,omitempty"`
	HeightMm *float64            `json:"height_mm,omitempty"`
	Format   string              `json:"format"`
	Channel  *string             `json:"channel,omitempty"`
	Blocks   []MarkingLabelBlock `json:"blocks"`
}

type MarkingLabelTemplateUsage struct {
	// General — По умолчанию для всего остального
	General  bool     `json:"general"`
	Channels []string `json:"channels"`
	Contacts []string `json:"contacts"`
	Products []string `json:"products"`
}

type MarkingLabelTemplates struct {
	Templates []MarkingLabelTemplate `json:"templates"`
	Fields    []string               `json:"fields"`
	Channels  []string               `json:"channels"`
	// Presets — Варианты оформления: только код, код и подпись, полная, маркетплейс (штрихкод площадки), марка и EAN-13
	Presets []string `json:"presets"`
	// GalleryPresets — Варианты оформления в галерее выбора
	GalleryPresets []string `json:"gallery_presets"`
	// DefaultTemplate — Шаблон, когда ни запрос, ни юрлицо его не назвали
	DefaultTemplate string   `json:"default_template"`
	Reasons         []string `json:"reasons"`
	// Outputs — Куда печатать: html — на принтер из браузера, pdf — файлом
	Outputs []string                    `json:"outputs"`
	Limits  MarkingLabelTemplatesLimits `json:"limits"`
}

type MarkingLabelTemplatesLimits struct {
	// Codes — Кодов в одной печати
	Codes int64 `json:"codes"`
	// Copies — Копий на код
	Copies int64 `json:"copies"`
	// Labels — Этикеток в одной печати
	Labels int64 `json:"labels"`
}

type MarkingModList struct {
	Mods []MarkingModListModsItem `json:"mods"`
}

type MarkingModListModsItem struct {
	KPP           string   `json:"kpp"`
	FiasID        string   `json:"fias_id"`
	Address       string   `json:"address"`
	INN           *string  `json:"inn,omitempty"`
	ProductGroups []string `json:"product_groups,omitempty"`
}

type MarkingOrderCode struct {
	ID   UUID   `json:"id"`
	Gtin string `json:"gtin"`
	// Seq — Порядковый номер кода в заказе по GTIN
	Seq *int64 `json:"seq"`
	// Identity — Код без криптохвоста
	Identity string           `json:"identity"`
	State    MarkingCodeState `json:"state"`
	// Printed — Этикеток напечатано без тестовых
	Printed int64 `json:"printed"`
	// Duplicates — Из них дубликатов
	Duplicates int64 `json:"duplicates"`
	// ApplicationID — Живой отчёт о нанесении кода
	ApplicationID *string `json:"application_id"`
	// SpoiledNote — Пояснение к испорченному коду
	SpoiledNote string  `json:"spoiled_note"`
	SpoiledAt   *string `json:"spoiled_at"`
}

type MarkingOrderCodes struct {
	Order MarkingCodeOrder `json:"order"`
	// ApplicationMode — Как наносятся коды группы заказа
	ApplicationMode string                    `json:"application_mode"`
	Gtins           []MarkingOrderGtinSummary `json:"gtins"`
	Items           []MarkingOrderCode        `json:"items"`
	// Total — Кодов по отбору
	Total        int64                  `json:"total"`
	PrintJobs    []MarkingOrderPrintJob `json:"print_jobs"`
	Applications []MarkingApplication   `json:"applications"`
	// Rejects — Коды, что СУЗ выдала, но в реестр они не легли
	Rejects []MarkingOrderRejectSummary `json:"rejects"`
}

type MarkingOrderGtinSummary struct {
	Gtin        string  `json:"gtin"`
	ProductID   *string `json:"product_id"`
	ProductName string  `json:"product_name"`
	// Quantity — Заказано
	Quantity int64 `json:"quantity"`
	// Received — Получено в реестр
	Received int64 `json:"received"`
	// Printed — Напечатано хотя бы раз
	Printed int64 `json:"printed"`
	// Applying — В отчёте о нанесении в обработке
	Applying int64 `json:"applying"`
	// Applied — Нанесено, включая введённые в оборот
	Applied int64 `json:"applied"`
	// Introducing — В отправленном документе ввода
	Introducing int64 `json:"introducing"`
	// Introduced — В обороте
	Introduced int64 `json:"introduced"`
	// Spoiled — Испорчено
	Spoiled int64 `json:"spoiled"`
	// Unprinted — Получено и ещё не напечатано, не нанесено и не испорчено
	Unprinted int64 `json:"unprinted"`
	// Applicable — Можно отметить нанесёнными
	Applicable int64 `json:"applicable"`
	// Introducible — Нанесено, но ещё не вводится и не в обороте
	Introducible int64 `json:"introducible"`
}

type MarkingOrderInput struct {
	CompanyID     UUID   `json:"company_id"`
	ProductGroup  string `json:"product_group"`
	ReleaseMethod string `json:"release_method"`
	// CisType — Вид кода всех строк; пусто — UNIT
	CisType       *string `json:"cis_type,omitempty"`
	ContactPerson *string `json:"contact_person,omitempty"`
	// PaymentType — Оплата кодов (attributes.paymentType): 1 — при эмиссии, 2 — при нанесении, 0 или нет поля — не передавать. Только у групп с выбором оплаты; REAPPLY ставит 1 сам
	PaymentType *int64 `json:"payment_type,omitempty"`
	// Signature — Откреплённая подпись УКЭП (CMS в base64) тела заказа из «Подготовить заказ»; СУЗ без неё заказ отклоняет
	Signature *string                      `json:"signature,omitempty"`
	Items     []MarkingOrderInputItemsItem `json:"items"`
}

type MarkingOrderInputItemsItem struct {
	// Gtin — GTIN из 14 цифр
	Gtin      string `json:"gtin"`
	Quantity  int64  `json:"quantity"`
	ProductID *UUID  `json:"product_id,omitempty"`
	// TemplateID — Шаблон кода СУЗ; 0 — по группе
	TemplateID *int64 `json:"template_id,omitempty"`
}

type MarkingOrderPrintJob struct {
	ID        UUID   `json:"id"`
	CreatedAt string `json:"created_at"`
	CreatedBy *int64 `json:"created_by"`
	Reason    string `json:"reason"`
	Template  string `json:"template"`
	Copies    int64  `json:"copies"`
	Note      string `json:"note"`
	// Ranges — Диапазоны номеров напечатанных кодов по GTIN
	Ranges []MarkingSeqRange `json:"ranges"`
}

type MarkingOrderReceiveResult struct {
	Order       MarkingCodeOrder `json:"order"`
	ReceivedNow int64            `json:"received_now"`
	Duplicates  int64            `json:"duplicates"`
	// Rejected — Не разобраны по формату группы: сохранены шифротекстом, разбираются заново
	Rejected int64 `json:"rejected"`
	// Bound — Коды юрлица, бывшие в реестре без заказа, привязаны к заказу (входят в received_now)
	Bound int64 `json:"bound"`
	// Conflicts — Коды, что числятся за другим юрлицом: не привязаны, сохранены неразобранными
	Conflicts int64 `json:"conflicts"`
	HasMore   bool  `json:"has_more"`
}

type MarkingOrderRejectSummary struct {
	Gtin string `json:"gtin"`
	// Reason — Код причины: ошибка разбора (format_mismatch, invalid_length …), invalid или other_company
	Reason string `json:"reason"`
	Count  int64  `json:"count"`
	// Sample — Начало одного такого кода без криптохвоста
	Sample string `json:"sample"`
}

type MarkingOrderReparseResult struct {
	Order MarkingCodeOrder `json:"order"`
	// ReceivedNow — Легло в реестр сейчас
	ReceivedNow int64 `json:"received_now"`
	Bound       int64 `json:"bound"`
	Duplicates  int64 `json:"duplicates"`
	// Rejected — Осталось неразобранными по формату
	Rejected int64 `json:"rejected"`
	// Conflicts — Осталось за другим юрлицом
	Conflicts int64 `json:"conflicts"`
}

type MarkingOrderSyncResult struct {
	Seen    int64 `json:"seen"`
	Created int64 `json:"created"`
	Updated int64 `json:"updated"`
}

