type SettingsPermissionAction struct {
	// Permission — Строка права для поля permissions роли
	Permission string  `json:"permission"`
	Verb       string  `json:"verb"`
	Label      string  `json:"label"`
	Hint       *string `json:"hint,omitempty"`
	// Implies — Строки, которые ставятся вместе с этой: изменение без просмотра не откроет экран
	Implies []string `json:"implies"`
	// Level — Ступень шкалы своей строки (у действия модуля — шкалы модуля): 1 — «Смотрит», 2 — «Работает». Ступень из нескольких строк ставится и снимается целиком
	Level *int64 `json:"level,omitempty"`
	// Extra — Группа блока «Дополнительные права»: money — деньги и цены, outside — подпись и отправка наружу, others — решения по чужому, people — данные людей, admin — администрирование модулей. Действие без level и extra редактор не показывает, строка остаётся допустимой
	Extra *string `json:"extra,omitempty"`
	// Includes — Строки, которые сервер даёт вместе с этим правом. Только для показа: в роль не пишутся
	Includes []string `json:"includes,omitempty"`
}

type SettingsPermissionCatalog struct {
	Modules []SettingsPermissionModule `json:"modules"`
	// Wildcards — Строки полного доступа: их выдаёт только администратор кабинета
	Wildcards []string `json:"wildcards"`
}

type SettingsPermissionModule struct {
	Key      string  `json:"key"`
	Label    string  `json:"label"`
	LabelKey *string `json:"label_key,omitempty"`
	// Enabled — Модуль включён в кабинете
	Enabled     bool                           `json:"enabled"`
	Actions     []SettingsPermissionAction     `json:"actions"`
	Units       []SettingsPermissionUnit       `json:"units"`
	RecordRules []SettingsPermissionRecordRule `json:"record_rules"`
}

type SettingsPermissionRecordRule struct {
	Resource string   `json:"resource"`
	Label    string   `json:"label"`
	Rules    []string `json:"rules"`
	// Unit — Строка карточки, у которой редактор показывает «Чьи»; пусто — шапка модуля
	Unit *string `json:"unit,omitempty"`
	// Action — Дополнительное право, к которому относится «Чьи»
	Action *string `json:"action,omitempty"`
}

type SettingsPermissionUnit struct {
	// Key — Полный ключ раздела или ресурса: модуль.единица
	Key      string  `json:"key"`
	Kind     string  `json:"kind"`
	Label    string  `json:"label"`
	LabelKey *string `json:"label_key,omitempty"`
	Hint     *string `json:"hint,omitempty"`
	// Exclusive — Право на модуль единицу не покрывает: выдаётся только своей строкой
	Exclusive bool `json:"exclusive"`
	// Technical — Ресурс выдаётся разделом; своей галочки в редакторе нет, но строка допустима
	Technical bool                       `json:"technical"`
	Actions   []SettingsPermissionAction `json:"actions"`
	// Heading — Ключ подзаголовка внутри карточки модуля: группа меню финансов, настройки CRM или склада
	Heading *string `json:"heading,omitempty"`
	// HeadingLabel — Подзаголовок на языке запроса
	HeadingLabel *string `json:"heading_label,omitempty"`
	// Card — Виртуальная карточка редактора вместо карточки модуля: trade — «Продажи и закупки»
	Card *string `json:"card,omitempty"`
	// Inherit — До какой ступени строку покрывает право модуля: 2 — целиком, 1 — только «Смотрит», 0 — не покрывает
	Inherit int64 `json:"inherit"`
}

