// StockContactPolicy — Складские настройки контрагента (ERP-1821): порог остаточного срока годности для отгрузок этому покупателю и для поставок на склад, посредник которого — этот контрагент (agent_contact_id склада назначения; у склада «в пути» — склада, для которого он путь; ERP-2182). Он сильнее порога кабинета и слабее порогов магазина площадки и документа.
type StockContactPolicy struct {
	ContactID   UUID   `json:"contact_id"`
	ContactName string `json:"contact_name"`
	// MinShelfLifePct — Порог остаточного срока для покупателя, % срока: десятичная строка. null — не задан
	MinShelfLifePct *string `json:"min_shelf_life_pct"`
	// MinShelfLifeDays — Порог остаточного срока для покупателя в днях до «годен до». null — не задан
	MinShelfLifeDays *int64 `json:"min_shelf_life_days"`
	// MinShelfLifeScale — Порог контрагента шкалой по общему сроку (ERP-2182). Всегда полный: одно значение — одна ступень без границы. При шкале из двух и более ступеней min_shelf_life_pct и min_shelf_life_days — null
	MinShelfLifeScale map[string]json.RawMessage `json:"min_shelf_life_scale"`
	UpdatedAt         string                     `json:"updated_at"`
}

// StockContactPolicyInput — Настройки контрагента сохраняются целиком: непереданное значение порога становится пустым. Порог пуст — настройки контрагента удаляются, действует порог кабинета.
type StockContactPolicyInput struct {
	ContactID UUID `json:"contact_id"`
	// MinShelfLifePct — Обычная десятичная запись больше 0 и не больше 100, не точнее сотых: «30», «12.5»
	MinShelfLifePct  *string `json:"min_shelf_life_pct,omitempty"`
	MinShelfLifeDays *int64  `json:"min_shelf_life_days,omitempty"`
	// MinShelfLifeScale — Порог шкалой по общему сроку (ERP-2182): прислан непустым — задаёт порог целиком, min_shelf_life_pct и min_shelf_life_days рядом не читаются. Неверная шкала — 400 shelf_life_minimum_scale_invalid
	MinShelfLifeScale *StockShelfLifeScale `json:"min_shelf_life_scale,omitempty"`
}

